mapper.select:
SELECT
    COUNT(*)
FROM accommodations a
LEFT JOIN users u ON a.host_id = u.user_id

    a.accommodation_id IS NOT NULL



        AND a.sido_code = #{sidoCode}


        AND a.gugun_code = #{gugunCode}


        AND a.status = #{status}




        AND a.accommodation_type = #{accommodationType}




        AND (a.title LIKE CONCAT('%', #{keyword}, '%')
        OR a.description LIKE CONCAT('%', #{keyword}, '%')
        OR a.address LIKE CONCAT('%', #{keyword}, '%'))




        AND EXISTS (
        SELECT 1 FROM rooms r
        WHERE r.accommodation_id = a.accommodation_id

            AND r.price BETWEEN #{minPrice} AND #{maxPrice}


            AND r.price >= #{minPrice}


            AND r.price <= #{maxPrice}

        )




        AND EXISTS (
        SELECT 1
        FROM rooms r
        WHERE r.accommodation_id = a.accommodation_id
        AND r.capacity >= #{guestCount}
        )

